function lastItem(list) {
  if (list.length === 0) return null;
  return list[list.length - 1];
}

function firstItem(list) {
  if (list.length === 0) return null;
  return list[0];
}

function shippingCost(weightKg) {
  if (weightKg < 0) throw new Error("weight cannot be negative");
  if (weightKg <= 5) return 4.99;
  if (weightKg <= 10) return 8.99;
  return 14.99;
}

function discountPercent(spend) {
  if (spend < 0) throw new Error("spend cannot be negative");
  if (spend >= 100) return 10;
  if (spend >= 50) return 5;
  return 0;
}

function pageCount(itemCount, perPage) {
  if (perPage < 1) throw new Error("perPage must be at least 1");
  return Math.ceil(itemCount / perPage);
}

function firstOrDefault(list, fallback) {
  if (list.length === 0) return fallback;
  return list[0];
}
